-- =====================================================================
-- Модуль «Жалобы». Миграция 002: решение по жалобам на уровне закупки.
--
--   test_buy_complaint       решение по жалобам: один цикл обжалования
--                            закупки (аналог test_buy)
--   test_buy_complaint_lots  решение по лоту закупки (аналог test_buy_lots)
--   test_complaint_answers   ответ уполномоченного органа
--
-- Файлы 002–004 выполняются вместе в одной транзакции:
--   psql --single-transaction -f 002_… -f 003_… -f 004_…
--
-- Соглашения модуля:
--   - id — GENERATED BY DEFAULT: php-activerecord вставляет id явно,
--     через nextval('<таблица>_id_seq');
--   - *_user_id, *_org_id, *_file_id объявлены без REFERENCES:
--     таблицы проекта модулю не известны;
--   - сроки — полуинтервал [starts_at, ends_at), проверка now() < ends_at;
--   - физическое удаление не применяется: deleted_at, is_current, annulled.
--
-- Не обеспечивается СУБД, проверяет PHP:
--   - test_buy_complaint_lots.test_buy_lots_id принадлежит закупке
--     test_buy_complaint.buy_id;
--   - тип решения по лоту согласуется с вердиктами жалоб лота.
-- =====================================================================

CREATE TABLE test_buy_complaint (
    id                    bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    buy_id                bigint      NOT NULL REFERENCES test_buy (id),
    authority_org_id      bigint      NOT NULL,             -- уполномоченный орган
    protocol_published_at timestamptz NOT NULL,             -- протокол итогов
    appeal_starts_at      timestamptz NOT NULL,
    appeal_ends_at        timestamptz NOT NULL,
    review_starts_at      timestamptz NOT NULL,
    review_ends_at        timestamptz NOT NULL,

    status                varchar(30) NOT NULL DEFAULT 'in_review',
    review_method         varchar(30),                      -- способ рассмотрения

    reviewer_user_id      bigint,                           -- закреплённый рассматривающий
    coordinator_user_id   bigint,                           -- необязателен
    approver_user_id      bigint,
    sent_for_approval_at  timestamptz,

    decision_number       varchar(50),                      -- Р-<номер закупки>[/N]
    approved_at           timestamptz,

    execution_status      varchar(30),
    execution_starts_at   timestamptz,
    execution_ends_at     timestamptz,
    executed_at           timestamptz,

    created_at            timestamptz NOT NULL DEFAULT now(),
    updated_at            timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT uq_buy_complaint_id_buy
        UNIQUE (id, buy_id),
    CONSTRAINT uq_buy_complaint_buy_period
        UNIQUE (buy_id, appeal_ends_at),
    CONSTRAINT uq_buy_complaint_decision_number
        UNIQUE (decision_number),
    CONSTRAINT chk_buy_complaint_status
        CHECK (status IN ('in_review', 'on_coordination', 'on_approval', 'recalled', 'approved')),
    CONSTRAINT chk_buy_complaint_review_method
        CHECK (review_method IN ('per_complaint', 'per_lot')),
    CONSTRAINT chk_buy_complaint_execution_status
        CHECK (execution_status IN ('not_required', 'in_progress', 'executed')),
    CONSTRAINT chk_buy_complaint_periods
        CHECK (appeal_starts_at < appeal_ends_at
           AND appeal_ends_at <= review_starts_at
           AND review_starts_at < review_ends_at),
    CONSTRAINT chk_buy_complaint_route
        CHECK (status NOT IN ('on_coordination', 'on_approval', 'approved')
            OR (review_method IS NOT NULL
                AND reviewer_user_id IS NOT NULL
                AND approver_user_id IS NOT NULL
                AND sent_for_approval_at IS NOT NULL)),
    CONSTRAINT chk_buy_complaint_coordinator
        CHECK (status <> 'on_coordination' OR coordinator_user_id IS NOT NULL),
    CONSTRAINT chk_buy_complaint_approved
        CHECK (status <> 'approved'
            OR (approved_at IS NOT NULL
                AND decision_number IS NOT NULL
                AND execution_status IS NOT NULL)),
    CONSTRAINT chk_buy_complaint_execution_after_approval
        CHECK (execution_status IS NULL OR status = 'approved'),
    CONSTRAINT chk_buy_complaint_execution_period
        CHECK (execution_status IS NULL
            OR execution_status = 'not_required'
            OR (execution_starts_at IS NOT NULL
                AND execution_ends_at IS NOT NULL
                AND execution_starts_at < execution_ends_at)),
    CONSTRAINT chk_buy_complaint_executed
        CHECK (execution_status IS DISTINCT FROM 'executed' OR executed_at IS NOT NULL)
);

COMMENT ON TABLE test_buy_complaint IS
    'Жалобы: решение по жалобам на закупку, один цикл обжалования (buy_id, appeal_ends_at)';

CREATE INDEX ix_buy_complaint_authority_status
    ON test_buy_complaint (authority_org_id, status);

CREATE INDEX ix_buy_complaint_execution
    ON test_buy_complaint (execution_status)
    WHERE execution_status IS NOT NULL;


CREATE TABLE test_buy_complaint_lots (
    id                    bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    test_buy_complaint_id bigint      NOT NULL REFERENCES test_buy_complaint (id),
    test_buy_lots_id      bigint      NOT NULL REFERENCES test_buy_lots (id),

    decision_type         varchar(30),
    execution_status      varchar(30),
    execution_started_at  timestamptz,
    executed_at           timestamptz,
    executed_by_user_id   bigint,

    created_at            timestamptz NOT NULL DEFAULT now(),
    updated_at            timestamptz NOT NULL DEFAULT now(),

    CONSTRAINT uq_buy_complaint_lots_complaint_buy_lot
        UNIQUE (test_buy_complaint_id, test_buy_lots_id),
    CONSTRAINT uq_buy_complaint_lots_id_buy_lot
        UNIQUE (id, test_buy_lots_id),
    CONSTRAINT chk_buy_complaint_lots_decision_type
        CHECK (decision_type IN ('cancel_purchase', 'revise_results', 'no_action')),
    CONSTRAINT chk_buy_complaint_lots_execution_status
        CHECK (execution_status IN ('pending', 'started', 'executed')),
    CONSTRAINT chk_buy_complaint_lots_execution_needs_decision
        CHECK (execution_status IS NULL
            OR decision_type IN ('cancel_purchase', 'revise_results')),
    CONSTRAINT chk_buy_complaint_lots_executed
        CHECK (execution_status IS DISTINCT FROM 'executed' OR executed_at IS NOT NULL)
);

COMMENT ON TABLE test_buy_complaint_lots IS
    'Жалобы: решение по лоту закупки и его исполнение';

CREATE INDEX ix_buy_complaint_lots_buy_lot
    ON test_buy_complaint_lots (test_buy_lots_id);


-- per_complaint: один ответ на один лот жалобы;
-- per_lot:       один ответ на все жалобы по лоту закупки.
CREATE TABLE test_complaint_answers (
    id                         bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    test_buy_complaint_lots_id bigint         NOT NULL REFERENCES test_buy_complaint_lots (id),
    answer_text                varchar(20000) NOT NULL,
    created_by_user_id         bigint         NOT NULL,
    created_at                 timestamptz    NOT NULL DEFAULT now(),
    updated_at                 timestamptz    NOT NULL DEFAULT now(),
    deleted_at                 timestamptz,

    CONSTRAINT uq_complaint_answers_id_buy_lot
        UNIQUE (id, test_buy_complaint_lots_id)
);

COMMENT ON TABLE test_complaint_answers IS
    'Жалобы: ответ уполномоченного органа по лоту решения';

CREATE INDEX ix_complaint_answers_buy_lot
    ON test_complaint_answers (test_buy_complaint_lots_id)
    WHERE deleted_at IS NULL;
